import asyncio

from playwright.async_api import async_playwright


async def main():
    async with async_playwright() as playwright:
        browser = await playwright.chromium.launch(channel="chrome", headless=True)
        page = await browser.new_page()
        await page.set_content('''<div class="subject_describe"><div id="stem"></div></div><script>
            document.querySelector('#stem').attachShadow({mode:'closed'}).innerHTML =
                '<p>公开显示的题干</p><img alt="题图">';
        </script>''')
        stem = page.locator(".subject_describe")
        print("DOM", repr(await stem.inner_text()))
        print("ARIA", repr(await stem.aria_snapshot()))
        print("Selection", repr(await stem.evaluate('''element => {
            const selection = window.getSelection();
            selection.selectAllChildren(element);
            const text = selection.toString();
            selection.removeAllRanges();
            return text;
        }''')))
        await browser.close()


asyncio.run(main())
